var RPERSONALIDADE_LIMITE=3;
function rPersonalidadeLimparNome(valor){return String(valor||"").replace(/\u00a0/g," ").replace(/\s+/g," ").replace(/^[\s|;:\-–—]+|[\s|;:\-–—]+$/g,"").trim()}
function rPersonalidadeExtrairTexto(texto){var itens=[],visto=Object.create(null);texto=String(texto||"").replace(/\u00a0/g," ");var padrao=/((?:https?:)?\/\/[^,\s<>"']+)\s*,\s*([\s\S]*?)(?=(?:(?:https?:)?\/\/)|$)/gi,achado;while((achado=padrao.exec(texto))!==null){var url=String(achado[1]||"").trim(),nome=rPersonalidadeLimparNome(achado[2]);if(!url||!nome)continue;var chave=url.toLowerCase()+"|"+nome.toLowerCase();if(visto[chave])continue;visto[chave]=true;itens.push({url:url,nome:nome})}return itens}
function rPersonalidadeJuntarItens(destino,novos,visto){(novos||[]).forEach(function(item){if(!item||!item.url)return;var nome=rPersonalidadeLimparNome(item.nome)||"Traço de personalidade",chave=String(item.url).toLowerCase()+"|"+nome.toLowerCase();if(visto[chave])return;visto[chave]=true;destino.push({url:String(item.url).trim(),nome:nome})})}
function rPersonalidadeItensDaRaiz(raiz){var itens=[],visto=Object.create(null);if(!raiz)return itens;raiz.querySelectorAll("img[src]").forEach(function(img){var url=img.getAttribute("src")||"",nome=img.getAttribute("title")||img.getAttribute("alt")||"";nome=nome.replace(/^Traço de personalidade:\s*/i,"");if(/^(?:https?:)?\/\//i.test(url))rPersonalidadeJuntarItens(itens,[{url:url,nome:nome}],visto)});rPersonalidadeJuntarItens(itens,rPersonalidadeExtrairTexto(raiz.textContent||""),visto);return itens}
function rPersonalidadeItemDoControle(input){if(!input)return null;var candidatos=[input.value||""],rotulo=input.closest("label");if(rotulo)candidatos.push(rotulo.textContent||"");candidatos.push(input.parentElement?input.parentElement.textContent||"":"");for(var i=0;i<candidatos.length;i++){var itens=rPersonalidadeExtrairTexto(candidatos[i]);if(itens.length)return itens[0]}return null}
function rPersonalidadeItensDoCampo(campo){if(!campo)return[];var visual=campo.querySelector(".field_uneditable"),itens=rPersonalidadeItensDaRaiz(visual);if(itens.length)return itens;var vistos=Object.create(null);campo.querySelectorAll('.field_editable input[type="checkbox"]:checked,.field_editable input[type="radio"]:checked').forEach(function(input){var item=rPersonalidadeItemDoControle(input);if(item)rPersonalidadeJuntarItens(itens,[item],vistos)});return itens}
function rPersonalidadeMontarLista(itens){var lista=document.createElement("ul");lista.className="profile_field_list";(itens||[]).forEach(function(item){var li=document.createElement("li"),img=document.createElement("img");img.src=item.url;img.title=item.nome;img.alt="Traço de personalidade: "+item.nome;img.decoding="async";li.appendChild(img);lista.appendChild(li)});return lista}
function rPersonalidadeAtualizarVisual(campo,conteudo){if(campo&&campo.jquery)campo=campo[0];if(!campo||!campo.classList.contains("profile-field-personalidade"))return;var visual=campo.querySelector(".field_uneditable");if(!visual){campo.classList.add("rpersonalidade-pronta");return}var itens=[];if(conteudo!==undefined&&conteudo!==null){var temporario=document.createElement("div");temporario.innerHTML=String(conteudo);itens=rPersonalidadeItensDaRaiz(temporario)}if(!itens.length)itens=rPersonalidadeItensDoCampo(campo);if(itens.length)visual.replaceChildren(rPersonalidadeMontarLista(itens));campo.classList.add("rpersonalidade-pronta")}
function rPersonalidadeAtualizarLimite(campo,inputAlterado){if(!campo)return;var editor=campo.querySelector(".rpersonalidade-editor");if(!editor)return;var controles=Array.from(editor.querySelectorAll('input[type="checkbox"],input[type="radio"]')),marcados=controles.filter(function(input){return input.checked});if(inputAlterado&&inputAlterado.checked&&marcados.length>RPERSONALIDADE_LIMITE){inputAlterado.checked=false;marcados=controles.filter(function(input){return input.checked})}if(!inputAlterado&&marcados.length>RPERSONALIDADE_LIMITE){marcados.slice(RPERSONALIDADE_LIMITE).forEach(function(input){input.checked=false});marcados=marcados.slice(0,RPERSONALIDADE_LIMITE)}var limiteAtingido=marcados.length>=RPERSONALIDADE_LIMITE;controles.forEach(function(input){var bloquear=limiteAtingido&&!input.checked;input.disabled=bloquear;var rotulo=input.closest(".rpersonalidade-opcao");if(rotulo)rotulo.classList.toggle("rpersonalidade-opcao-bloqueada",bloquear)});var contador=editor.querySelector(".rpersonalidade-contador");if(contador)contador.textContent=marcados.length+"/"+RPERSONALIDADE_LIMITE}
function rPersonalidadePosicionarEditor(campo){if(!campo)return;var editor=campo.querySelector(".rpersonalidade-editor:not(.invisible)");if(!editor)return;var margem=8,distancia=8,larguraMaxima=280,alturaMaxima=300,viewportLargura=document.documentElement.clientWidth||window.innerWidth,viewportAltura=document.documentElement.clientHeight||window.innerHeight,campoRect=campo.getBoundingClientRect(),limites={left:margem,top:margem,right:viewportLargura-margem,bottom:viewportAltura-margem},ancestral=campo.parentElement;while(ancestral&&ancestral!==document.body){var estilo=getComputedStyle(ancestral);if(/auto|scroll|hidden|clip/.test(estilo.overflowX+" "+estilo.overflowY)){var ancestralRect=ancestral.getBoundingClientRect();limites.left=Math.max(limites.left,ancestralRect.left+margem);limites.top=Math.max(limites.top,ancestralRect.top+margem);limites.right=Math.min(limites.right,ancestralRect.right-margem);limites.bottom=Math.min(limites.bottom,ancestralRect.bottom-margem)}ancestral=ancestral.parentElement}var areaLargura=Math.max(0,limites.right-limites.left),largura=Math.min(larguraMaxima,areaLargura),espacoDireita=limites.right-campoRect.right-distancia,espacoEsquerda=campoRect.left-limites.left-distancia,espacoAbaixo=limites.bottom-campoRect.bottom-distancia,espacoAcima=campoRect.top-limites.top-distancia,alturaPeloTopo=limites.bottom-campoRect.top,cabeAoLado=viewportLargura>620&&Math.max(espacoDireita,espacoEsquerda)>=largura;editor.classList.remove("rpersonalidade-editor-esquerda","rpersonalidade-editor-abaixo","rpersonalidade-editor-acima");editor.style.setProperty("--rpersonalidade-deslocamento-x","0px");if(!cabeAoLado){var abrirAbaixo=espacoAbaixo>=150||espacoAbaixo>=espacoAcima,espacoVertical=abrirAbaixo?espacoAbaixo:espacoAcima,esquerdaIdeal=campoRect.left+(campoRect.width-largura)/2,esquerdaMaxima=Math.max(limites.left,limites.right-largura),esquerdaFinal=Math.min(Math.max(esquerdaIdeal,limites.left),esquerdaMaxima);editor.classList.add(abrirAbaixo?"rpersonalidade-editor-abaixo":"rpersonalidade-editor-acima");editor.style.setProperty("--rpersonalidade-deslocamento-x",esquerdaFinal-campoRect.left+"px");editor.style.setProperty("--rpersonalidade-altura",Math.max(80,Math.min(alturaMaxima,espacoVertical))+"px")}else{if(espacoDireita<largura&&espacoEsquerda>espacoDireita)editor.classList.add("rpersonalidade-editor-esquerda");editor.style.setProperty("--rpersonalidade-altura",Math.max(80,Math.min(alturaMaxima,alturaPeloTopo))+"px")}editor.style.setProperty("--rpersonalidade-largura",largura+"px")}
function rPersonalidadePrepararEditor(campo){if(!campo)return;var editor=campo.querySelector(".field_editable");if(!editor)return;editor.classList.add("rpersonalidade-editor");var painel=editor.querySelector(":scope > .rpersonalidade-painel");if(!painel){painel=document.createElement("div");painel.className="rpersonalidade-painel";editor.prepend(painel)}var cabecalho=painel.querySelector(":scope > .rpersonalidade-editor-cabecalho");if(!cabecalho){cabecalho=document.createElement("div");cabecalho.className="rpersonalidade-editor-cabecalho";var titulo=document.createElement("span");titulo.textContent="Selecione até 3 traços";var contador=document.createElement("small");contador.className="rpersonalidade-contador";contador.textContent="0/"+RPERSONALIDADE_LIMITE;cabecalho.appendChild(titulo);cabecalho.appendChild(contador);painel.appendChild(cabecalho)}var lista=painel.querySelector(":scope > .rpersonalidade-lista");if(!lista){lista=document.createElement("div");lista.className="rpersonalidade-lista";painel.appendChild(lista)}editor.querySelectorAll('input[type="checkbox"],input[type="radio"]').forEach(function(input){var item=rPersonalidadeItemDoControle(input),rotulo=input.closest("label");if(!item||!rotulo)return;rotulo.classList.add("rpersonalidade-opcao");rotulo.setAttribute("title",item.nome);input.setAttribute("aria-label",item.nome);var visual=rotulo.querySelector(":scope > .rpersonalidade-opcao-visual");if(!visual){visual=document.createElement("span");visual.className="rpersonalidade-opcao-visual";var img=document.createElement("img");img.src=item.url;img.alt="";img.decoding="async";var nome=document.createElement("span");nome.className="rpersonalidade-opcao-nome";nome.textContent=item.nome;visual.appendChild(img);visual.appendChild(nome);rotulo.appendChild(visual)}if(rotulo.parentElement!==lista)lista.appendChild(rotulo)});editor.querySelectorAll(":scope > br").forEach(function(br){br.remove()});Array.from(editor.childNodes).forEach(function(no){if(no.nodeType===Node.TEXT_NODE&&!no.textContent.trim())no.remove()});if(!editor.dataset.rpersonalidadeLimite){editor.addEventListener("change",function(evento){if(evento.target.matches('input[type="checkbox"],input[type="radio"]'))rPersonalidadeAtualizarLimite(campo,evento.target)});editor.dataset.rpersonalidadeLimite="true"}rPersonalidadeAtualizarLimite(campo)}
function rPersonalidadeProcessarCampo(campo){if(!campo||campo.classList.contains("rpersonalidade-pronta"))return;rPersonalidadePrepararEditor(campo);rPersonalidadeAtualizarVisual(campo)}
function rPersonalidadeInicializar(raiz){raiz=raiz||document;if(raiz.nodeType===1&&raiz.matches&&raiz.matches("#main-profile .profile-field-personalidade"))rPersonalidadeProcessarCampo(raiz);if(raiz.querySelectorAll)raiz.querySelectorAll("#main-profile .profile-field-personalidade:not(.rpersonalidade-pronta)").forEach(rPersonalidadeProcessarCampo)}
var rPersonalidadeObservador=new MutationObserver(function(mudancas){mudancas.forEach(function(mudanca){mudanca.addedNodes.forEach(function(no){if(no.nodeType===1)rPersonalidadeInicializar(no)})})});rPersonalidadeObservador.observe(document.documentElement,{childList:true,subtree:true});document.addEventListener("click",function(evento){var botao=evento.target.closest("#main-profile .profile-field-personalidade .ajax-profil_edit");if(!botao)return;var campo=botao.closest(".profile-field-personalidade");requestAnimationFrame(function(){rPersonalidadeAtualizarLimite(campo);rPersonalidadePosicionarEditor(campo)})});var rPersonalidadeReposicionamentoPendente=false;function rPersonalidadeReposicionarAberto(){if(rPersonalidadeReposicionamentoPendente)return;rPersonalidadeReposicionamentoPendente=true;requestAnimationFrame(function(){rPersonalidadeReposicionamentoPendente=false;document.querySelectorAll("#main-profile .profile-field-personalidade").forEach(rPersonalidadePosicionarEditor)})}window.addEventListener("resize",rPersonalidadeReposicionarAberto);if(document.readyState==="loading")document.addEventListener("DOMContentLoaded",function(){rPersonalidadeInicializar(document)});else rPersonalidadeInicializar(document);
